export type DashIconName = keyof typeof ICON_RENDERERS

interface DashSvgProps {
  name: DashIconName
  color?: string
  className?: string
  width?: string
  height?: string
  viewBox?: string
  triggered?: boolean
}

export const DashSvg = ({
  name,
  color = 'currentColor',
  className = 'text-text-primary',
  width = '20',
  height = '20',
  viewBox = '0 0 20 20',
  triggered = false,
}: DashSvgProps) => {
  const svgProps: BaseSvgProps = {
    className,
    width,
    height,
    viewBox,
    style: { color },
    xmlns: 'http://www.w3.org/2000/svg',
  }

  const renderer = ICON_RENDERERS[name]

  if (!renderer) {
    return null
  }

  return renderer({ svgProps, triggered })
}

